// src/api/tmdb.js
const API_KEY = "발급받은_TMDB_API_KEY_입력"; // 혹은 기존에 쓰시던 키 설정
const BASE_URL = "https://api.themoviedb.org/3";
const LANGUAGE = "ko-KR";

// 기존에 쓰시던 최신 영화 목록 함수
export const getLatestMovies = async () => {
  try {
    const response = await fetch(`${BASE_URL}/movie/now_playing?api_key=${API_KEY}&language=${LANGUAGE}&page=1`);
    const data = await response.json();
    
    return data.results.map(movie => ({
      id: movie.id.toString(),
      title: movie.title,
      year: movie.release_date ? movie.release_date.split('-')[0] : '2026',
      age: movie.adult ? '19+' : '15+',
      duration: '1h 50m',
      language: movie.original_language ? movie.original_language.toUpperCase() : 'KO',
      director: '감독 정보 준비중',
      synopsis: movie.overview,
      genres: [movie.genre_ids ? '드라마' : '영화'],
      rating: movie.vote_average ? movie.vote_average.toFixed(1) : '9.5',
      poster: movie.poster_path ? `https://image.tmdb.org/t/p/w500${movie.poster_path}` : '/img/default_poster.jpg',
      backdrop: movie.backdrop_path ? `https://image.tmdb.org/t/p/original${movie.backdrop_path}` : null,
      gallery: []
    }));
  } catch (error) {
    console.error("TMDB API 오류:", error);
    return [];
  }
};

// 💡 새로 추가해야 하는 영화 상세 정보 및 스틸컷 연동 함수
export const getMovieDetails = async (id) => {
  try {
    // 1. 영화 기본 상세 정보 및 크레딧(감독/출연진), 이미지(스틸컷) 동시 요청
    const [detailRes, creditsRes, imagesRes] = await Promise.all([
      fetch(`${BASE_URL}/movie/${id}?api_key=${API_KEY}&language=${LANGUAGE}`),
      fetch(`${BASE_URL}/movie/${id}/credits?api_key=${API_KEY}&language=${LANGUAGE}`),
      fetch(`${BASE_URL}/movie/${id}/images?api_key=${API_KEY}`)
    ]);

    const detail = await detailRes.json();
    const credits = await creditsRes.json();
    const images = await imagesRes.json();

    // 감독 찾기
    const directorObj = credits.crew?.find(person => person.job === 'Director');
    const director = directorObj ? directorObj.name : '감독 정보 없음';

    // 출연진 상위 5명
    const casts = credits.cast ? credits.cast.slice(0, 5).map(c => c.name).join(', ') : '출연진 정보 없음';

    // 스틸컷(백드롭 이미지들) 상위 3장
    const gallery = images.backdrops ? images.backdrops.slice(0, 3).map(img => `https://image.tmdb.org/t/p/w500${img.file_path}`) : [];

    return {
      id: detail.id.toString(),
      title: detail.title,
      year: detail.release_date ? detail.release_date.split('-')[0] : '2026',
      age: detail.adult ? '19+' : '15+',
      duration: detail.runtime ? `${Math.floor(detail.runtime / 60)}h ${detail.runtime % 60}m` : '1h 50m',
      language: detail.original_language ? detail.original_language.toUpperCase() : 'KO',
      director: director,
      casts: casts,
      synopsis: detail.overview || '줄거리가 없습니다.',
      genres: detail.genres ? detail.genres.map(g => g.name) : [],
      rating: detail.vote_average ? detail.vote_average.toFixed(1) : '9.5',
      poster: detail.poster_path ? `https://image.tmdb.org/t/p/w500${detail.poster_path}` : null,
      backdrop: detail.backdrop_path ? `https://image.tmdb.org/t/p/original${detail.backdrop_path}` : null,
      gallery: gallery
    };
  } catch (error) {
    console.error("영화 상세 데이터 연동 실패:", error);
    return null;
  }
};
